using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;
    private static ScenarioRunConfiguration _scenarios = null!;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        _scenarios = ScenarioRunConfiguration.Load("evaluation.yml");

        var builder = DistributedApplication.CreateBuilder();
        builder.AddAzureOpenAIChatClient("chat", "gpt-4o-mini");
        var app = await builder.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = app.Services.GetRequiredService<IChatClient>();
    }

    [TestMethod]
    [DynamicData(nameof(GetScenarios), DynamicDataSourceType.Method)]
    public async Task EvaluateScenario(string scenarioName)
    {
        var scenario = _scenarios[scenarioName];
        var messages = new List<ChatMessage>();

        ChatCompletion? lastResponse = null;
        foreach (var turn in scenario.Turns)
        {
            messages.Add(new ChatMessage(ChatRole.User, turn.User));
            lastResponse = await _chatClient.GetResponseAsync(messages);
            messages.Add(lastResponse.Message);
        }

        Assert.IsNotNull(lastResponse, "No response received from the chat client.");

        var evaluators = CreateEvaluators(scenario);
        var result = await evaluators.EvaluateAsync(messages, lastResponse, _evaluatorClient);

        foreach (var criterion in scenario.Criteria)
        {
            var score = result[criterion.Metric];
            Assert.IsTrue(
                score.NumericValue >= criterion.Threshold,
                $"Scenario '{scenarioName}': {criterion.Metric} score {score.NumericValue} " +
                $"is below threshold {criterion.Threshold}. Reason: {score.Reason}");
        }
    }

    private static CompositeEvaluator CreateEvaluators(ScenarioDefinition scenario)
    {
        var evaluators = new List<IEvaluator>();

        var metrics = scenario.Criteria.Select(c => c.Metric).Distinct();
        foreach (var metric in metrics)
        {
            evaluators.Add(metric switch
            {
                "relevance" => new RelevanceEvaluator(),
                "coherence" => new CoherenceEvaluator(),
                "fluency" => new FluencyEvaluator(),
                "groundedness" => new GroundednessEvaluator(),
                _ => throw new InvalidOperationException($"Unknown metric: {metric}")
            });
        }

        return new CompositeEvaluator(evaluators.ToArray());
    }

    private static IEnumerable<object[]> GetScenarios()
    {
        var scenarios = ScenarioRunConfiguration.Load("evaluation.yml");
        foreach (var name in scenarios.ScenarioNames)
        {
            yield return new object[] { name };
        }
    }
}

using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;

namespace MyApp.Evaluation;

/// <summary>
/// Loads and represents the evaluation scenario definitions from evaluation.yml.
/// </summary>
public class ScenarioRunConfiguration
{
    private readonly Dictionary<string, ScenarioDefinition> _scenarios;

    public IEnumerable<string> ScenarioNames => _scenarios.Keys;

    public ScenarioDefinition this[string name] => _scenarios[name];

    private ScenarioRunConfiguration(Dictionary<string, ScenarioDefinition> scenarios)
    {
        _scenarios = scenarios;
    }

    public static ScenarioRunConfiguration Load(string path)
    {
        var yaml = File.ReadAllText(path);
        var deserializer = new DeserializerBuilder()
            .WithNamingConvention(UnderscoredNamingConvention.Instance)
            .Build();

        var config = deserializer.Deserialize<EvaluationConfig>(yaml);
        var dict = config.Scenarios.ToDictionary(s => s.Name);
        return new ScenarioRunConfiguration(dict);
    }
}

public class EvaluationConfig
{
    public List<ScenarioDefinition> Scenarios { get; set; } = new();
}

public class ScenarioDefinition
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<TurnDefinition> Turns { get; set; } = new();
    public List<CriterionDefinition> Criteria { get; set; } = new();
}

public class TurnDefinition
{
    public string User { get; set; } = string.Empty;
}

public class CriterionDefinition
{
    public string Metric { get; set; } = string.Empty;
    public double Threshold { get; set; }
}

